// Reading what charts hold beyond their series and axes: data labels, the
// axes of a second scale, turned labels and levels of categories, radar,
// bubble and stock charts, a pie with a second plot, trend lines, error bars,
// drop lines, high-low lines, up-down bars, places set by hand, logarithmic
// and date axes. Every chart part is generated by code.

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { chartCachedPoints, parseChart } from '../src/formats/xlsx/chart';
import { chartCacheList, MAX_CHART_TRENDLINES, type Chart } from '../src/model/sheet/chart';
import { parseXml } from '../src/xml';
import { OFFICE_THEME, catAx, chartXml, group, numLit, numRef, readChart, ser, solid, spPr, strLit, strRef, title, valAx, xyAxes, xySer, legend } from './chart-fixtures';

function must(xml: string): Chart {
  const chart = readChart(xml);
  assert.ok(chart, 'the chart is read');
  return chart as Chart;
}

const CATS = strLit(['a', 'b', 'c']);
const bars = (series: string, tail = '') => chartXml({ plot: group('barChart', '<c:barDir val="col"/><c:grouping val="clustered"/>', series, tail) + catAx() + valAx() });
const scattered = (series: string) => chartXml({ plot: group('scatterChart', '<c:scatterStyle val="lineMarker"/>', series) + xyAxes() });
const noted = (chart: Chart, pattern: RegExp) => chart.notes.some((note) => pattern.test(note));

test('data labels: what they show, where, in which format and look, at the chart type, the series and the point', () => {
  const rich = '<c:tx><c:rich><a:bodyPr/><a:p><a:r><a:t>En </a:t></a:r><a:r><a:t>büyük</a:t></a:r></a:p></c:rich></c:tx>';
  const chart = must(
    bars(
      ser(0, {
        cat: CATS,
        val: numLit([1, 2, 3]),
        props:
          '<c:dLbls>' +
          `<c:dLbl><c:idx val="2"/>${rich}<c:dLblPos val="inEnd"/><c:showVal val="1"/></c:dLbl>` +
          '<c:dLbl><c:idx val="1"/><c:delete val="1"/></c:dLbl>' +
          '<c:dLbl><c:idx val="-4"/><c:showVal val="1"/></c:dLbl>' +
          '<c:numFmt formatCode="0.00" sourceLinked="0"/>' +
          `<c:txPr><a:bodyPr/><a:p><a:pPr><a:defRPr sz="1200" b="1">${solid('FF0000')}</a:defRPr></a:pPr></a:p></c:txPr>` +
          '<c:dLblPos val="outEnd"/><c:showLegendKey val="1"/><c:showVal val="1"/><c:showCatName val="1"/><c:showSerName val="0"/><c:showPercent val="0"/><c:showBubbleSize val="0"/><c:separator>; </c:separator>' +
          '</c:dLbls>',
      }) +
        ser(1, { val: numLit([4, 5, 6]), props: '<c:dLbls><c:delete val="1"/></c:dLbls>' }) +
        ser(2, { val: numLit([4, 5, 6]) }),
      '<c:dLbls><c:showLegendKey val="0"/><c:showVal val="0"/><c:showSerName val="1"/><c:dLblPos val="nowhere"/></c:dLbls>',
    ),
  );
  const [a, b, c] = chart.groups[0].series;
  assert.deepEqual(a.dataLabels, {
    showValue: true,
    showCategory: true,
    showSeries: false,
    showPercent: false,
    showBubbleSize: false,
    showLegendKey: true,
    separator: '; ',
    formatCode: '0.00',
    sourceLinked: false,
    position: 'outEnd',
    style: { size: 12, bold: true, color: '#FF0000' },
  });
  assert.deepEqual(a.pointLabels, [
    { index: 1, deleted: true },
    { index: 2, showValue: true, position: 'inEnd', text: 'En büyük' },
  ]);
  assert.deepEqual(b.dataLabels, { deleted: true });
  assert.equal(c.dataLabels, undefined);
  assert.deepEqual(chart.groups[0].dataLabels, { showLegendKey: false, showValue: false, showSeries: true }, 'a position that is none is left to the chart type');
  assert.ok(noted(chart, /legend key/i), 'the key of the legend in a label is noted');
  assert.ok(!noted(chart, /Data labels are not drawn/), 'labels are drawn now');
});

test('the axes: both pairs of a chart with a second scale, sides, turned labels, time units, a logarithmic base', () => {
  const chart = must(
    chartXml({
      plot:
        group('barChart', '<c:barDir val="col"/>', ser(0, { cat: CATS, val: numLit([1, 2, 3]) })) +
        '<c:lineChart><c:grouping val="standard"/>' +
        ser(1, { cat: CATS, val: numLit([100, 200, 300]) }) +
        '<c:axId val="333"/><c:axId val="444"/></c:lineChart>' +
        catAx('<c:txPr><a:bodyPr rot="-2700000" vert="horz"/><a:p><a:pPr><a:defRPr/></a:pPr></a:p></c:txPr>') +
        valAx('', '<c:logBase val="10"/><c:orientation val="minMax"/>') +
        '<c:dateAx><c:axId val="333"/><c:scaling><c:orientation val="minMax"/></c:scaling><c:delete val="1"/><c:axPos val="t"/><c:crossAx val="444"/><c:baseTimeUnit val="months"/><c:majorUnit val="3"/><c:majorTimeUnit val="months"/></c:dateAx>' +
        '<c:valAx><c:axId val="444"/><c:scaling><c:logBase val="5000"/></c:scaling><c:delete val="0"/><c:axPos val="r"/><c:tickLblPos val="high"/><c:crossAx val="333"/><c:crosses val="max"/></c:valAx>',
    }),
  );
  const [cat, val, date, second] = chart.axes;
  assert.equal(cat.labelRotation, -45);
  assert.equal(val.logBase, 10);
  assert.deepEqual([date.date, date.deleted, date.position, date.baseTimeUnit, date.majorTimeUnit, date.majorUnit], [true, true, 't', 'months', 'months', 3]);
  assert.deepEqual([second.position, second.crosses, second.tickLabels, second.logBase], ['r', 'max', 'high', undefined], 'a base that is none is no base');
  assert.deepEqual(chart.groups[1].axisIds, [333, 444]);
  assert.ok(!noted(chart, /secondary axis/), 'a second scale is drawn, not noted');
  assert.ok(!noted(chart, /logarithmic axis is drawn as a linear/), 'so is a logarithmic axis');
  assert.ok(noted(chart, /not above zero/), 'what a logarithmic axis leaves out is noted');
  const turned = (rot: string) => must(chartXml({ plot: group('barChart', '', ser(0, { val: numLit([1]) })) + catAx(`<c:txPr><a:bodyPr rot="${rot}"/><a:p/></c:txPr>`) + valAx() })).axes[0].labelRotation;
  assert.deepEqual([turned('5400000'), turned('-5400000'), turned('0'), turned('99999999'), turned('x')], [90, -90, 0, 90, undefined]);
});

test('levels of categories: the level next to the axis and the ones beyond it', () => {
  const levels =
    '<c:multiLvlStrRef><c:f>S!$A$1:$B$4</c:f><c:multiLvlStrCache><c:ptCount val="4"/>' +
    '<c:lvl><c:pt idx="0"><c:v>Oca</c:v></c:pt><c:pt idx="1"><c:v>Şub</c:v></c:pt><c:pt idx="2"><c:v>Oca</c:v></c:pt><c:pt idx="3"><c:v>Şub</c:v></c:pt></c:lvl>' +
    '<c:lvl><c:pt idx="0"><c:v>2024</c:v></c:pt><c:pt idx="2"><c:v>2025</c:v></c:pt></c:lvl>' +
    '<c:lvl><c:pt idx="0"><c:v>Hepsi</c:v></c:pt></c:lvl>' +
    '</c:multiLvlStrCache></c:multiLvlStrRef>';
  const chart = must(bars(ser(0, { cat: levels, val: numLit([1, 2, 3, 4]) })));
  const data = chart.groups[0].series[0].categories;
  assert.deepEqual(chartCacheList(data), ['Oca', 'Şub', 'Oca', 'Şub']);
  assert.deepEqual(data?.levels, [
    { index: [0, 2], values: ['2024', '2025'] },
    { index: [0], values: ['Hepsi'] },
  ]);
  assert.equal(data?.count, 4);
  assert.ok(noted(chart, /more than two levels/), 'a third level is noted');
  assert.equal(chartCachedPoints(chart), 4 + 3 + 4, 'every level counts against the budget');
});

test('a radar chart, a bubble chart and a stock chart are charts of the model', () => {
  const radar = (style: string) => must(chartXml({ plot: group('radarChart', style, ser(0, { cat: CATS, val: numLit([1, 2, 3]) })) + catAx() + valAx() })).groups[0];
  assert.deepEqual([radar('<c:radarStyle val="filled"/>').kind, radar('<c:radarStyle val="filled"/>').radarStyle], ['radar', 'filled']);
  assert.equal(radar('<c:radarStyle val="marker"/>').radarStyle, 'marker');
  assert.equal(radar('<c:radarStyle val="spiral"/>').radarStyle, 'standard');
  assert.equal(radar('').radarStyle, 'standard');

  const bubbles = must(
    chartXml({
      plot:
        group(
          'bubbleChart',
          '<c:varyColors val="0"/>',
          `<c:ser><c:idx val="0"/><c:order val="0"/><c:xVal>${numRef('S!$A$1:$A$3', [1, 2, 3])}</c:xVal><c:yVal>${numLit([4, 5, 6])}</c:yVal><c:bubbleSize>${numLit([10, -20, 30])}</c:bubbleSize><c:bubble3D val="1"/></c:ser>`,
          '<c:bubbleScale val="50"/><c:showNegBubbles val="1"/><c:sizeRepresents val="w"/>',
        ) + xyAxes(),
    }),
  );
  const bubble = bubbles.groups[0];
  assert.deepEqual([bubble.kind, bubble.bubbleScale, bubble.showNegBubbles, bubble.sizeRepresents], ['bubble', 50, true, 'w']);
  assert.deepEqual(chartCacheList(bubble.series[0].categories), [1, 2, 3], 'x');
  assert.deepEqual(chartCacheList(bubble.series[0].values), [4, 5, 6], 'y');
  assert.deepEqual(chartCacheList(bubble.series[0].bubbleSizes), [10, -20, 30], 'sizes');
  assert.equal(chartCachedPoints(bubbles), 9, 'the sizes count against the budget');
  const plain = must(chartXml({ plot: group('bubbleChart', '', xySer(0, { cat: numLit([1]), val: numLit([2]) }), '<c:bubbleScale val="9000"/>') + xyAxes() })).groups[0];
  assert.deepEqual([plain.bubbleScale, plain.showNegBubbles, plain.sizeRepresents], [300, undefined, undefined]);

  const stock = must(
    chartXml({
      plot:
        group(
          'stockChart',
          '',
          [0, 1, 2, 3].map((i) => ser(i, { cat: CATS, val: numLit([i, i + 1, i + 2]), props: spPr('<a:ln w="28575"><a:noFill/></a:ln>') })).join(''),
          `<c:hiLowLines>${spPr(`<a:ln w="9525">${solid('112233')}</a:ln>`)}</c:hiLowLines><c:upDownBars><c:gapWidth val="150"/><c:upBars>${spPr(solid('FFFFFF'))}</c:upBars><c:downBars>${spPr(solid('000000'))}</c:downBars></c:upDownBars>`,
        ) +
        catAx() +
        valAx(),
    }),
  ).groups[0];
  assert.equal(stock.kind, 'stock');
  assert.equal(stock.series.length, 4);
  assert.deepEqual(stock.hiLowLines, { color: '#112233', width: 1 });
  assert.deepEqual(stock.upDownBars, { gapWidth: 150, up: { fill: '#FFFFFF' }, down: { fill: '#000000' } });
});

test('a pie with a second plot is read as a pie that knows which points the second plot takes; a surface chart is a chart of its own kind', () => {
  const of = (inner: string) => must(chartXml({ plot: group('ofPieChart', '<c:ofPieType val="bar"/><c:varyColors val="1"/>', ser(0, { cat: CATS, val: numLit([1, 2, 3]) }), inner, false) }));
  const chart = of('<c:splitType val="pos"/><c:splitPos val="2"/>');
  assert.equal(chart.groups[0].kind, 'pie');
  assert.deepEqual(chart.groups[0].ofPie, { split: 'pos', position: 2 });
  assert.ok(noted(chart, /second plot/), 'what is left out is noted');
  assert.deepEqual(of('').groups[0].ofPie, { split: 'auto' });
  assert.deepEqual(of('<c:splitType val="percent"/><c:splitPos val="12.5"/>').groups[0].ofPie, { split: 'percent', position: 12.5 });
  assert.deepEqual(of('<c:splitType val="cust"/><c:custSplit><c:secondPiePt val="0"/><c:secondPiePt val="2"/><c:secondPiePt val="-1"/></c:custSplit>').groups[0].ofPie, { split: 'cust', points: [0, 2] });
  for (const name of ['surfaceChart', 'surface3DChart']) {
    assert.equal(readChart(chartXml({ plot: group(name, '', ser(0, { val: numLit([1]) })) + catAx() + valAx() }))?.groups[0].kind, 'surface', name);
  }
});

test('trend lines and error bars of a series', () => {
  const trend = (inner: string) => `<c:trendline>${inner}</c:trendline>`;
  const chart = must(
    scattered(
      xySer(0, {
        cat: numLit([1, 2, 3]),
        val: numLit([1, 2, 3]),
        tail: '',
        props:
          trend(`<c:name>Eğilim</c:name>${spPr(`<a:ln w="19050">${solid('00FF00')}<a:prstDash val="sysDot"/></a:ln>`)}<c:trendlineType val="poly"/><c:order val="3"/><c:forward val="2"/><c:backward val="0.5"/><c:dispRSqr val="1"/><c:dispEq val="1"/>`) +
          trend('<c:trendlineType val="movingAvg"/><c:period val="2"/>') +
          trend('<c:trendlineType val="poly"/><c:order val="99"/>') +
          trend('<c:trendlineType val="exp"/><c:forward val="-3"/><c:intercept val="2"/>') +
          trend('<c:trendlineType val="wavy"/>') +
          ['log', 'power', 'linear'].map((type) => trend(`<c:trendlineType val="${type}"/>`)).join('') +
          trend('<c:trendlineType val="linear"/>').repeat(5) +
          `<c:errBars><c:errDir val="y"/><c:errBarType val="plus"/><c:errValType val="percentage"/><c:noEndCap val="1"/><c:val val="10"/>${spPr(`<a:ln w="9525">${solid('0000FF')}</a:ln>`)}</c:errBars>` +
          `<c:errBars><c:errDir val="x"/><c:errBarType val="both"/><c:errValType val="cust"/><c:noEndCap val="0"/><c:plus>${numLit([1, 2, 3])}</c:plus><c:minus>${numRef('S!$C$1:$C$3', [0.5, 0.5, 0.5])}</c:minus></c:errBars>` +
          '<c:errBars><c:errDir val="y"/><c:errBarType val="both"/><c:errValType val="stdErr"/></c:errBars>',
      }),
    ),
  );
  const series = chart.groups[0].series[0];
  const lines = series.trendlines || [];
  assert.equal(lines.length, MAX_CHART_TRENDLINES, 'no more trend lines than the limit');
  assert.deepEqual(lines[0], { type: 'poly', order: 3, forward: 2, backward: 0.5, name: 'Eğilim', line: { color: '#00FF00', width: 2, dash: true } });
  assert.deepEqual(lines[1], { type: 'movingAvg', period: 2 });
  assert.deepEqual(lines[2], { type: 'poly', order: 6 }, 'a degree is kept within 2..6');
  const periods = must(
    scattered(xySer(0, { cat: numLit([1, 2]), val: numLit([1, 2]), props: ['1', '-7', '4', '99999999', 'x'].map((period) => trend(`<c:trendlineType val="movingAvg"/><c:period val="${period}"/>`)).join('') + trend('<c:trendlineType val="poly"/><c:order val="1"/>') })),
  ).groups[0].series[0].trendlines || [];
  assert.deepEqual(periods.map((line) => line.period ?? line.order), [2, 2, 4, 100000, 2, 2], 'a period is at least two points and at most as many as a series may have; a degree is at least two');
  assert.deepEqual(lines[3], { type: 'exp' }, 'a length that is none is none');
  assert.deepEqual(lines.slice(4, 7).map((line) => line.type), ['log', 'power', 'linear'], 'a type that is none is no trend line');
  assert.ok(noted(chart, /equation/i) && noted(chart, /intercept/i), 'the equation, R² and a set intercept are noted');
  const [y, x] = series.errorBars || [];
  assert.equal((series.errorBars || []).length, 2, 'one set of bars along each axis');
  assert.deepEqual(y, { direction: 'y', type: 'plus', valueType: 'percentage', value: 10, noEndCap: true, line: { color: '#0000FF', width: 1 } });
  assert.deepEqual([x.direction, x.type, x.valueType, x.noEndCap], ['x', 'both', 'cust', undefined]);
  assert.deepEqual(chartCacheList(x.plus), [1, 2, 3]);
  assert.deepEqual([x.minus?.ref, chartCacheList(x.minus)], ['S!$C$1:$C$3', [0.5, 0.5, 0.5]]);
  assert.equal(chartCachedPoints(chart), 3 + 3 + 6, 'the amounts count against the budget');
  assert.ok(!noted(chart, /Trend lines are not drawn|Error bars are not drawn/), 'both are drawn now');
  const upright = must(bars(ser(0, { val: numLit([1]), props: '<c:errBars><c:errDir val="x"/><c:errBarType val="both"/><c:errValType val="fixedVal"/><c:val val="1"/></c:errBars>' })));
  assert.equal(upright.groups[0].series[0].errorBars?.[0].direction, 'y', 'a chart type without horizontal values has bars along its values only');
});

test('lines of a line chart: drop lines, high-low lines, up-down bars; a smoothed series is no longer noted', () => {
  const chart = must(
    chartXml({
      plot:
        group(
          'lineChart',
          '<c:grouping val="standard"/>',
          ser(0, { val: numLit([1, 2]), tail: '<c:smooth val="1"/>' }) + ser(1, { val: numLit([2, 1]) }),
          `<c:dropLines>${spPr(`<a:ln>${solid('AA0000')}</a:ln>`)}</c:dropLines><c:hiLowLines/><c:upDownBars><c:gapWidth val="9999"/><c:upBars/><c:downBars/></c:upDownBars><c:marker val="1"/>`,
        ) +
        catAx() +
        valAx(),
    }),
  );
  const line = chart.groups[0];
  assert.deepEqual(line.dropLines, { color: '#AA0000' });
  assert.deepEqual(line.hiLowLines, {});
  assert.deepEqual(line.upDownBars, { gapWidth: 500 });
  assert.equal(line.series[0].smooth, true);
  assert.ok(!noted(chart, /drawn straight|Drop lines/), 'nothing of it is noted as not drawn');
  const area = must(chartXml({ plot: group('areaChart', '<c:grouping val="standard"/>', ser(0, { val: numLit([1, 2]) }), '<c:dropLines/>') + catAx() + valAx() }));
  assert.deepEqual(area.groups[0].dropLines, {});
  const withSeriesLines = must(chartXml({ plot: group('barChart', '<c:barDir val="col"/><c:grouping val="stacked"/>', ser(0, { val: numLit([1, 2]) }), '<c:serLines/>') + catAx() + valAx() }));
  assert.ok(noted(withSeriesLines, /Series lines/), 'series lines of stacked bars are still not drawn');
});

test('places set by hand, slices that are pulled out, and what is still only noted', () => {
  const manual = (inner: string) => `<c:layout><c:manualLayout>${inner}</c:manualLayout></c:layout>`;
  const xml =
    '<?xml version="1.0"?><c:chartSpace xmlns:c="http://schemas.openxmlformats.org/drawingml/2006/chart" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><c:chart>' +
    title('Başlık').replace('<c:overlay', `${manual('<c:xMode val="edge"/><c:yMode val="factor"/><c:x val="0.25"/><c:y val="-0.1"/>')}<c:overlay`) +
    `<c:plotArea>${manual('<c:layoutTarget val="inner"/><c:xMode val="edge"/><c:yMode val="edge"/><c:x val="0.1"/><c:y val="0.2"/><c:w val="0.6"/><c:h val="0.5"/>')}` +
    group('pieChart', '<c:varyColors val="1"/>', ser(0, { cat: CATS, val: numLit([1, 2, 3]), props: '<c:explosion val="25"/><c:dPt><c:idx val="1"/><c:explosion val="900"/></c:dPt><c:dPt><c:idx val="2"/><c:explosion val="0"/></c:dPt>' }), '', false) +
    '<c:dTable><c:showHorzBorder val="1"/></c:dTable></c:plotArea>' +
    legend('r', manual('<c:x val="0.8"/><c:y val="0.3"/><c:w val="0.15"/><c:h val="nope"/>')) +
    '</c:chart></c:chartSpace>';
  const chart = parseChart(parseXml(xml).root, OFFICE_THEME) as Chart;
  assert.ok(chart, 'the chart is read');
  assert.deepEqual(chart.title?.layout, { xMode: 'edge', yMode: 'factor', x: 0.25, y: -0.1 });
  assert.deepEqual(chart.plotLayout, { target: 'inner', xMode: 'edge', yMode: 'edge', x: 0.1, y: 0.2, w: 0.6, h: 0.5 });
  assert.deepEqual(chart.legend?.layout, { x: 0.8, y: 0.3, w: 0.15 });
  const series = chart.groups[0].series[0];
  assert.equal(series.explosion, 25);
  assert.deepEqual(series.points, [{ index: 1, explosion: 400 }, { index: 2, explosion: 0 }]);
  assert.ok(!noted(chart, /set by hand|pulled out/), 'neither is noted as not applied');
  assert.ok(noted(chart, /data table/i), 'the data table is still noted');
});

test('a series name that is a reference, and labels, on every new chart type do not throw whatever they hold', () => {
  const junk = '<c:dLbls><c:dLbl/><c:dLbl><c:idx val="x"/></c:dLbl><c:numFmt/><c:separator/><c:txPr/></c:dLbls><c:trendline/><c:errBars/><c:errBars><c:errValType val="cust"/><c:plus/></c:errBars><c:explosion val="x"/>';
  for (const name of ['radarChart', 'bubbleChart', 'stockChart', 'ofPieChart', 'lineChart', 'scatterChart']) {
    const xy = name === 'bubbleChart' || name === 'scatterChart';
    const series = xy ? xySer(0, { tx: strRef('S!$A$1', ['Ad']), cat: numLit([1]), val: numLit([2]), props: junk, tail: '<c:bubbleSize/>' }) : ser(0, { tx: strRef('S!$A$1', ['Ad']), val: numLit([2]), props: junk });
    const chart = readChart(chartXml({ plot: group(name, '', series, '<c:upDownBars/><c:hiLowLines><c:spPr/></c:hiLowLines><c:custSplit/>') + catAx() + valAx() }));
    assert.ok(chart, `${name} is read`);
    assert.equal(chart?.groups[0].series[0].name?.text, 'Ad', name);
  }
});
